('topic-edx-igcse-maths-a-01', 'subj-edx-igcse-maths-a', 'Numbers and the number system', 'Integers, fractions, decimals, powers, roots, standard form, percentages, ratio, proportion, bounds, degree of accuracy, and surds.', 1, 14, 'medium', 12, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-edx-igcse-maths-a-02', 'subj-edx-igcse-maths-a', 'Equations, formulae and identities', 'Algebraic manipulation, expansion, factorisation, linear and quadratic equations, algebraic fractions, rearranging formulae, simultaneous equations, and inequalities.', 2, 12, 'hard', 14, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-edx-igcse-maths-a-03', 'subj-edx-igcse-maths-a', 'Sequences, functions and graphs', 'Arithmetic sequences, nth term, function notation, domain and range, composite and inverse functions, straight line graphs, gradients, and quadratic/cubic curve sketches.', 3, 9, 'medium', 10, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-edx-igcse-maths-a-04', 'subj-edx-igcse-maths-a', 'Geometry and trigonometry', 'Angles, polygons, parallel lines, circle theorems, constructions, Pythagoras theorem, sine/cosine rules, 3D trigonometry, and bearings.', 4, 11, 'hard', 12, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-edx-igcse-maths-a-05', 'subj-edx-igcse-maths-a', 'Vectors and transformation geometry', 'Column vectors, vector arithmetic, vector proofs of collinearity and parallel lines, reflections, rotations, translations, and enlargements.', 5, 6, 'hard', 8, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-edx-igcse-maths-a-06', 'subj-edx-igcse-maths-a', 'Statistics and probability', 'Averages, range, frequency polygons, cumulative frequency, histograms with unequal intervals, simple and combined probability, Venn diagrams, and tree diagrams.', 6, 8, 'medium', 8, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-edx-igcse-maths-a-07', 'subj-edx-igcse-maths-a', 'Calculus', 'Differentiation of polynomials, finding gradients, tangents and normals, stationary points, and kinematics applications.', 7, 5, 'hard', 8, strftime('%s','now')*1000, strftime('%s','now')*1000),
('topic-edx-igcse-maths-b-01', 'subj-edx-igcse-maths-b', 'Number and sets', 'Types of number, set theory and Venn diagrams, indices, standard form, fractions, decimals, percentages, ratio, proportion, and surds.', 1, 10, 'medium', 10, strftime('%s','now')*1000, strftime('%s','now')*1000),
